window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-173c17928370e6cb"]={"versions": [{"id": "FIG-173c17928370e6cb", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Sendevorgangs einer E2E-geschützten Botschaft über einen COM-Callout in der AUTOSAR Classic Platform. Das Diagramm illustriert den Kontroll- und Datenfluss von einer Software-Komponente (SWC) über RTE, COM und E2E Library bis zur Übergabe an den PDU-Router (PduR).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten und Module:</p>\n<ul class=\"fig-list\">\n<li><code>SWC</code>: Application Software Component als Datensender.</li>\n<li><code>«module» Rte</code>: Runtime Environment zur Signalvermittlung.</li>\n<li><code>«module» Com</code>: AUTOSAR COM-Modul mit Prozess-/Zyklussymbol zur Signalbündelung und I-PDU-Erzeugung.</li>\n<li><code>COM Callout IPDU_E2EProtect_21</code>: Anwenderspezifische Callout-Funktion zur Ausführung der Absicherung.</li>\n<li><code>«module» E2E</code>: AUTOSAR E2E Library zur Berechnung der Prüfdaten.</li>\n<li><code>«module» PduR</code>: PDU Router zur Weiterleitung an unterlagerte Kommunikationsschnittstellen.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Aufrufe:</p>\n<ul class=\"fig-list\">\n<li>Datenübertragung: <code>Data elements to transmit</code> (SWC an Rte), <code>Signals to transmit</code> (Rte an Com).</li>\n<li>Callout-Schnittstelle: <code>IPDU_E2EProtect_21(TxPduId, IPduInfo)</code>.</li>\n<li>E2E-Bibliotheksschnittstelle: <code>E2E_P01Protect(&amp;Settings, &amp;State, IPduInfo-&gt;SduDataPtr)</code>.</li>\n<li>PDU-Router-Schnittstelle: <code>PduR_ComTransmit()</code>.</li>\n<li>Rückflüsse / Datenübergaben: <code>Updated SduData</code> (asynchron/Rückgabe von E2E an Callout und Callout an Com).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die <code>SWC</code> sendet zu übertragende Datenelemente (<code>Data elements to transmit</code>) an die <code>Rte</code>.</li>\n<li>Die <code>Rte</code> leitet die Daten als Signale (<code>Signals to transmit</code>) an das Modul <code>Com</code> weiter.</li>\n<li><code>Com</code> assembliert intern die I-PDU (<code>Create I-PDU_21 out of signals, do necessary conversions e.g. endiannes</code>).</li>\n<li><code>Com</code> ruft den konfigurierten Callout <code>IPDU_E2EProtect_21(TxPduId, IPduInfo)</code> auf.</li>\n<li>Im Callout erfolgt (einmalig beim Systemstart) eine statische Initialisierung: <code>[One time at startup]:Hardcoded initialization of config and state structures</code>.</li>\n<li>Der Callout ruft die E2E-Profilfunktion <code>E2E_P01Protect(&amp;Settings, &amp;State, IPduInfo-&gt;SduDataPtr)</code> auf.</li>\n<li>Das Modul <code>E2E</code> berechnet die Schutzdaten (CRC, Sequenzzähler) über die Nutzdaten (<code>Execute protection algorithms</code>).</li>\n<li>Die aktualisierten Nutzdaten (<code>Updated SduData</code>) werden an den Callout und anschließend zurück an das Modul <code>Com</code> übergeben.</li>\n<li><code>Com</code> initiiert den Sendeauftrag an den PDU-Router über <code>PduR_ComTransmit()</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Sequenzdiagramm dient als Architektur- und Integrationsbeispiel für die Einbindung der E2E-Bibliothek über AUTOSAR COM-Callouts (E2E-Schutz unterhalb der RTE).</li>\n<li>Konfigurations- und Zustandsstrukturen (<code>Settings</code>, <code>State</code>) verbleiben im Kontext des Callouts und müssen vor der ersten Absicherung korrekt initialisiert vorliegen.</li>\n<li>Der PDU-Puffer (<code>IPduInfo-&gt;SduDataPtr</code>) wird direkt „in-place“ durch den E2E-Algorithmus modifiziert.</li>\n<li>Fehlerbehandlung oder Rückgabewerte (z. B. <code>E2E_E_OK</code>) der Protect-Funktion sowie des Callouts (z. B. Verwerfen/Unterdrücken der PDU) sind im Diagramm abstrahiert.</li>\n</ul>"}, {"id": "FIG-2dcff08623397586", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Sendevorgangs einer E2E-geschützten Botschaft über einen COM-Callout in der AUTOSAR Classic Platform. Das Diagramm illustriert den Kontroll- und Datenfluss von einer Software-Komponente (SWC) über RTE, COM und E2E Library bis zur Übergabe an den PDU-Router (PduR).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten und Module:</p>\n<ul class=\"fig-list\">\n<li><code>SWC</code>: Application Software Component als Datensender.</li>\n<li><code>«module» Rte</code>: Runtime Environment zur Signalvermittlung.</li>\n<li><code>«module» Com</code>: AUTOSAR COM-Modul mit Prozess-/Zyklussymbol zur Signalbündelung und I-PDU-Erzeugung.</li>\n<li><code>COM Callout IPDU_E2EProtect_21</code>: Anwenderspezifische Callout-Funktion zur Ausführung der Absicherung.</li>\n<li><code>«module» E2E</code>: AUTOSAR E2E Library zur Berechnung der Prüfdaten.</li>\n<li><code>«module» PduR</code>: PDU Router zur Weiterleitung an unterlagerte Kommunikationsschnittstellen.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Aufrufe:</p>\n<ul class=\"fig-list\">\n<li>Datenübertragung: <code>Data elements to transmit</code> (SWC an Rte), <code>Signals to transmit</code> (Rte an Com).</li>\n<li>Callout-Schnittstelle: <code>IPDU_E2EProtect_21(TxPduId, IPduInfo)</code>.</li>\n<li>E2E-Bibliotheksschnittstelle: <code>E2E_P01Protect(&amp;Settings, &amp;State, IPduInfo-&gt;SduDataPtr)</code>.</li>\n<li>PDU-Router-Schnittstelle: <code>PduR_ComTransmit()</code>.</li>\n<li>Rückflüsse / Datenübergaben: <code>Updated SduData</code> (asynchron/Rückgabe von E2E an Callout und Callout an Com).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die <code>SWC</code> sendet zu übertragende Datenelemente (<code>Data elements to transmit</code>) an die <code>Rte</code>.</li>\n<li>Die <code>Rte</code> leitet die Daten als Signale (<code>Signals to transmit</code>) an das Modul <code>Com</code> weiter.</li>\n<li><code>Com</code> assembliert intern die I-PDU (<code>Create I-PDU_21 out of signals, do necessary conversions e.g. endiannes</code>).</li>\n<li><code>Com</code> ruft den konfigurierten Callout <code>IPDU_E2EProtect_21(TxPduId, IPduInfo)</code> auf.</li>\n<li>Im Callout erfolgt (einmalig beim Systemstart) eine statische Initialisierung: <code>[One time at startup]:Hardcoded initialization of config and state structures</code>.</li>\n<li>Der Callout ruft die E2E-Profilfunktion <code>E2E_P01Protect(&amp;Settings, &amp;State, IPduInfo-&gt;SduDataPtr)</code> auf.</li>\n<li>Das Modul <code>E2E</code> berechnet die Schutzdaten (CRC, Sequenzzähler) über die Nutzdaten (<code>Execute protection algorithms</code>).</li>\n<li>Die aktualisierten Nutzdaten (<code>Updated SduData</code>) werden an den Callout und anschließend zurück an das Modul <code>Com</code> übergeben.</li>\n<li><code>Com</code> initiiert den Sendeauftrag an den PDU-Router über <code>PduR_ComTransmit()</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Sequenzdiagramm dient als Architektur- und Integrationsbeispiel für die Einbindung der E2E-Bibliothek über AUTOSAR COM-Callouts (E2E-Schutz unterhalb der RTE).</li>\n<li>Konfigurations- und Zustandsstrukturen (<code>Settings</code>, <code>State</code>) verbleiben im Kontext des Callouts und müssen vor der ersten Absicherung korrekt initialisiert vorliegen.</li>\n<li>Der PDU-Puffer (<code>IPduInfo-&gt;SduDataPtr</code>) wird direkt „in-place“ durch den E2E-Algorithmus modifiziert.</li>\n<li>Fehlerbehandlung oder Rückgabewerte (z. B. <code>E2E_E_OK</code>) der Protect-Funktion sowie des Callouts (z. B. Verwerfen/Unterdrücken der PDU) sind im Diagramm abstrahiert.</li>\n</ul>"}], "trans": [{"from": "FIG-173c17928370e6cb", "to": "FIG-2dcff08623397586", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
